import{z as i,x as n,o as l,c as A,q as B,j as t,D as E,d as e,s as d,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"连通分量与桥","description":"","frontmatter":{"title":"连通分量与桥","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bcc-bridge.md","filePath":"cs/bcc-bridge.md","lastUpdated":1791413859000}'),c={name:"cs/bcc-bridge.md"};function p(C,a,D,u,h,m){const r=n("Mermaid");return l(),A("div",null,[a[2]||(a[2]=B('<h1 id="连通分量与桥" tabindex="-1">连通分量与桥 <a class="header-anchor" href="#连通分量与桥" aria-label="Permalink to &quot;连通分量与桥&quot;">​</a></h1><div class="epigraph"><p>无向图上，删掉就使连通支数增加的边是桥；DFS 的 low 值在一次扫描里标出桥、割点与双连通块。</p><footer>—— 据 Tarjan, Depth-First Search and Linear Graph Algorithms, 1972；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/dfs-edge-types">DFS 与边分类</a>给出发现/完成时刻，以及有向环当且仅当反向边。无向图上非树边都连祖先，环的存在变成「有没有回边」，但<strong>哪条边是桥、哪个点是割点</strong>时刻不够用。本课不重做括号定理。缺口是 <code>low</code>：子树能摸到的最老祖先发现时刻。后课拓扑假定有向无环，本课先把无向连通的可切边收掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>边 \\(e\\) 是桥：删 \\(e\\) 后连通分量增多。点 \\(v\\) 是割点：删 \\(v\\) 后增多。双连通分量（BCC）：极大的、去掉任一点仍连通的边集块（实现上常按边划分）。缺口是线性算法，不是再 BFS 一遍看连通。</p><p>对树边 \\((u,v)\\)（\\(u\\) 父）：若 \\(v\\) 的子树没有任何回边摸到 \\(u\\) 或更老，则 \\((u,v)\\) 是桥。<code>low[v]=\\min(d[v],</code> 回边端点的 \\(d\\), 子树 <code>low)</code>。割点：根有不少于两棵子树；非根 \\(u\\) 存在孩子 \\(v\\) 使 <code>low[v]\\ge d[u]</code>。</p><p>有向图的强连通分量是另一划分：相互可达。Tarjan / Kosaraju 同为 \\(\\Theta(V+E)\\)。本课点名：有向环落在同一强连通块里；缩点之后才是 DAG。反向边判定环已经够用；SCC 是把环捏成点。</p><h3 id="low-不是距离" tabindex="-1">low 不是距离 <a class="header-anchor" href="#low-不是距离" aria-label="Permalink to &quot;low 不是距离&quot;">​</a></h3><p><code>low</code> 是发现时刻的最小可达，不是无权层数。<a href="/cs/bfs-unweighted">BFS</a> 的距离不管桥。不要用「叶子边都是桥」代替：有回边的叶子边不是桥。</p><p><span class="marginnote">Tarjan 1972 一次 DFS 做双连通与强连通。CLRS 把桥与割点放在 22.2–22.5 的习题与应用。后课拓扑只消费「无向环已能找、有向环已能判」。</span></p><p><span class="marginnote">直觉类比：把 DFS 树想成家谱，\\(d\\) 是「出生序号」，low 是「你能攀认的最年长长辈的序号」。树边 \\((u,v)\\) 是桥，就是 \\(v\\) 这一房攀不到 \\(u\\) 以外的任何长辈——把 \\(u\\)、\\(v\\) 之间的门拆掉，这一房就与全家断了走动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无向图：DFS 记父，避免把树边当回边扫两遍。维护 <code>d</code> 与 <code>low</code>，回溯时更新父的 <code>low</code>，按不等式报告桥与割点。边栈可弹出一个 BCC。全图 \\(\\Theta(V+E)\\)。</p>',13)),(l(),t(s,null,{default:E(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFS%5B%22DFS%20%E6%A0%91%20%2B%20%E5%9B%9E%E8%BE%B9%22%5D%20--%3E%20LOW%5B%22low%20%E6%97%B6%E5%88%BB%22%5D%0A%20%20LOW%20--%3E%20BR%5B%22%E6%A1%A5%20%2F%20%E5%89%B2%E7%82%B9%22%5D%0A%20%20LOW%20--%3E%20BCC%5B%22%E5%8F%8C%E8%BF%9E%E9%80%9A%E5%9D%97%22%5D%0A%20%20DIR%5B%22%E6%9C%89%E5%90%91%22%5D%20--%3E%20SCC%5B%22%E5%BC%BA%E8%BF%9E%E9%80%9A%E5%9D%97%20%E2%86%92%20DAG%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"孤立点、重边：重边使「那一条」不是桥。实现要决定平行边是否拆。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,[e("桥属于每一个过它的简单环的补：不在环上。BCC 之间恰在割点处粘连，像树。后课最短路、流都不假设双连通；本课只提供分解。也不要把连通分量（无向可达）与 BCC 混名：前者随便 BFS，后者要 "),o("code",null,"low"),e("。")],-1)),(l(),t(s,null,{default:E(()=>[d(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%9B%9E%E6%BA%AF%E5%AE%8C%E6%AF%95%2C%20%E5%AD%A9%E5%AD%90%20v%20%E5%90%91%E7%88%B6%E4%BA%B2%20u%20%E6%B1%87%E6%8A%A5%22%5D%20--%3E%20T%7B%22low%5Bv%5D%20%E8%83%BD%E6%91%B8%E5%88%B0%20u%20%E6%88%96%E6%9B%B4%E8%80%81%E5%90%97%3F%22%7D%0A%20%20T%20--%3E%7C%22%E6%91%B8%E4%B8%8D%E5%88%B0%22%7C%20BR%5B%22%E5%AD%90%E6%A0%91%E5%87%BA%20v%20%E5%8F%AA%E5%89%A9%20u-v%20%E4%B8%80%E6%9D%A1%E8%B7%AF%3A%20%E6%98%AF%E6%A1%A5%22%5D%0A%20%20T%20--%3E%7C%22%E6%91%B8%E5%BE%97%E5%88%B0%22%7C%20NB%5B%22%E6%9C%89%E5%9B%9E%E8%BE%B9%E5%85%9C%E5%BA%95%3A%20%E4%B8%8D%E6%98%AF%E6%A1%A5%22%5D%0A%20%20BR%20--%3E%20BCC%5B%22%E5%BC%B9%E5%87%BA%E8%BE%B9%E6%A0%88%2C%20%E6%94%B6%E4%B8%80%E4%B8%AA%E5%8F%8C%E8%BF%9E%E9%80%9A%E5%9D%97%22%5D%0A%20%20NB%20--%3E%20CONT%5B%22%E7%88%B6%E7%94%A8%20low%5Bv%5D%20%E6%9B%B4%E6%96%B0%20low%5Bu%5D%2C%20%E7%BB%A7%E7%BB%AD%E5%9B%9E%E6%BA%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：三点连成链 A-B-C，B-C 是桥（C 子树摸不到 A）；补一条回边 C-A 成三角形后，C 的 low 变成 \\(d(A)=1\\)，压到 \\(d(B)=2\\) 之下，两条边都不再是桥——一条回边就能救活整条链。</span></p><p><span class="marginnote">常见误区：初学者容易把「非根割点」的不等式硬套到根上。根没有更老的祖先可比，规则不同：根是割点当且仅当它在 DFS 树里长出不止一棵子树——子树之间除根外没有别的路，因为无向图没有横叉边。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算最短路，不写 2-SAT 的蕴含图。有向桥（边连通）更细，不展开。后课默认：无向桥与割点可线性标出；有向环 \\(\\Leftrightarrow\\) 反向边，缩 SCC 得 DAG。拓扑排序是下一课把 DAG 变成线性序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>low</code> 标出桥、割点与双连通块，仍 \\(\\Theta(V+E)\\)。</li><li>有向强连通缩点后才谈拓扑。</li><li>有向环判定仍用反向边，本课不重证。</li><li>出处：Tarjan, 1972；CLRS 第 22 章。</li></ul>',6))])}const T=i(c,[["render",p]]);export{f as __pageData,T as default};
